settings.custom_liquid:
{% assign product_collection = collections['kunststof-platen'] %}

<section class="home-material-section" aria-labelledby="home-material-title">
  <div class="home-material-section__inner">
    <header class="home-material-section__head">
      <div>
        <p>Onze kunststofsoorten</p>
        <h1 id="home-material-title">Naar welke kunststof plaat ben je op zoek?</h1>
      </div>
      <a href="/collections/kunststof-platen">Bekijk het assortiment <span aria-hidden="true">→</span></a>
    </header>

    <div class="home-material-grid">
      {% for product in product_collection.products limit: 6 %}
        <a href="{{ product.url }}" class="home-material-grid__item">
          <div class="home-material-grid__image">
            {% if product.featured_image %}
              {{
                product.featured_image
                | image_url: width: 600
                | image_tag:
                  loading: 'eager',
                  widths: '200, 300, 400, 600',
                  sizes: '(max-width: 749px) 138px, 190px',
                  alt: product.title
              }}
            {% endif %}
          </div>
          <div class="home-material-grid__title">{{ product.title }}</div>
          <span>Bekijk plaat <i aria-hidden="true">→</i></span>
        </a>
      {% endfor %}
    </div>
  </div>
</section>

<style>
  .home-material-section,.home-material-section *{box-sizing:border-box}
  .home-material-section{width:100%;padding:48px 0 36px;background:#fff;color:#14213d;font-family:inherit}
  .home-material-section__inner{width:min(1280px,calc(100% - 40px));margin:0 auto}
  .home-material-section__head{display:flex;align-items:end;justify-content:space-between;gap:36px;margin-bottom:30px}
  .home-material-section__head p{margin:0 0 9px;color:#1872c9;font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}
  .home-material-section__head h1{max-width:760px;margin:0;color:#14213d;font-size:clamp(31px,3.8vw,50px);font-weight:760;letter-spacing:-.04em;line-height:1.04}
  .home-material-section__head>a{display:inline-flex;align-items:center;gap:10px;padding-bottom:4px;color:#14213d;font-size:14px;font-weight:750;text-decoration:none;white-space:nowrap}
  .home-material-section__head>a span{color:#1872c9;font-size:18px}
  .home-material-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:22px}
  .home-material-grid__item{display:block;min-width:0;color:#14213d;text-align:center;text-decoration:none}
  .home-material-grid__image{width:100%;aspect-ratio:1;overflow:hidden;margin-bottom:13px;border:1px solid #dce4ec;border-radius:50%;background:#f5f7f9;transition:border-color .22s ease,transform .22s ease,box-shadow .22s ease}
  .home-material-grid__image img{display:block;width:100%;height:100%;object-fit:cover;border-radius:50%;transition:transform .28s ease}
  .home-material-grid__item:hover .home-material-grid__image{border-color:#b8c9da;box-shadow:0 10px 25px rgba(16,40,72,.08);transform:translateY(-3px)}
  .home-material-grid__item:hover .home-material-grid__image img{transform:scale(1.035)}
  .home-material-grid__title{overflow:hidden;font-size:16px;font-weight:750;line-height:1.25;text-overflow:ellipsis;white-space:nowrap}
  .home-material-grid__item>span{display:inline-flex;align-items:center;gap:5px;margin-top:5px;color:#6a7787;font-size:11px}
  .home-material-grid__item>span i{color:#1872c9;font-size:13px;font-style:normal}
  @media(max-width:989px){.home-material-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:26px}.home-material-section__head{align-items:flex-start;flex-direction:column;gap:14px}}
  @media(max-width:749px){
    .home-material-section{overflow:hidden;padding:35px 0 28px}
    .home-material-section__inner{width:100%}
    .home-material-section__head{padding:0 18px;margin-bottom:24px}
    .home-material-section__head h1{font-size:34px}
    .home-material-grid{display:flex;gap:15px;overflow-x:auto;padding:0 18px 10px;scroll-snap-type:x mandatory;scrollbar-width:none}
    .home-material-grid::-webkit-scrollbar{display:none}
    .home-material-grid__item{flex:0 0 138px;scroll-snap-align:start}
    .home-material-grid__title{font-size:14px}
  }
</style>

{% render 'kxl-home-hero' %}<!-- hero-type-v2 --><!-- hero-type-v5 --><style>
.kxl-home-hero,.kxl-home-hero__pill,.kxl-home-hero__content--secondary p{font-family:Helvetica,Arial,sans-serif}
.kxl-home-hero h2,.kxl-home-hero h3{font-family:Helvetica,Arial,sans-serif!important}
.kxl-home-hero h3{line-height:1.1}
.kxl-home-hero__pill{font-weight:750}
.kxl-home-hero__grid{align-items:stretch}
.kxl-home-hero__card{min-height:0}
.kxl-home-hero__card--secondary{aspect-ratio:1}
@media(max-width:900px){
  .kxl-home-hero__card{min-height:430px}
  .kxl-home-hero__card--secondary{width:min(100%,520px);min-height:0;aspect-ratio:1;justify-self:center}
}
@media(max-width:600px){
  .kxl-home-hero__card--secondary{width:100%;min-height:0;aspect-ratio:1}
}
</style>

{% liquid
  assign raw_uid = block.id | default: section.id | default: 'diagonal-banner'
  assign uid = raw_uid | replace: ':', '-' | replace: '.', '-' | replace: '/', '-'

  assign banner_h = 380
  assign diag_top_x = 5
  assign diag_bottom_x = 250
  assign fold_w = 28
  assign band_w = 44
  assign band_top_y = 62

  assign delta = diag_bottom_x | minus: diag_top_x
  assign diag_at_band_y = delta | times: band_top_y | divided_by: banner_h | plus: diag_top_x

  assign img_url_700 = 'https://cdn.shopify.com/s/files/1/0670/4168/9713/files/7206b6bc-21b9-4a57-8fb1-d297050df1ee.png?v=1778870167'
  assign img_url_mobile = 'https://cdn.shopify.com/s/files/1/0670/4168/9713/files/7206b6bc-21b9-4a57-8fb1-d297050df1ee.png?v=1778870167'
  assign image_alt = 'Maatwerk onderdelen'

  assign title = 'Maatwerk nodig?'
  assign subtitle = 'Bouwmarkt<span class="rt-xl">XL</span> denkt graag mee'
  assign description = 'Maatwerk en oplossingsgericht advies behoren tot onze sterkste punten. Kun je voor jouw toepassing niet het juiste product of een passende oplossing vinden? Neem dan gerust contact met ons op.'
  assign button_label = 'Contact opnemen'
  assign button_link = '/pages/maatwerk'
%}

<style>
 .rt-{{ uid }} {
  --rt-bg: #003878;
  --rt-btn-bg: #FF7300;
  --rt-btn-hover: #e66700;
  --rt-btn-text: #ffffff;
  --rt-text: #ffffff;
  --rt-radius: 8px;
  --rt-border: #A0B2C9;
}

.rt-{{ uid }}.rt-wrap {
  width: 100%;
  border-radius: var(--rt-radius);
  overflow: hidden;
  box-shadow: 0 20px 25px -5px rgba(0,0,0,.10), 0 10px 10px -5px rgba(0,0,0,.04);
  border: 1px solid var(--rt-border);
}

.rt-{{ uid }} .rt-banner {
  display: flex;
  min-height: {{ banner_h }}px;
  flex-direction: column;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-banner {
    flex-direction: row;
  }
}

.rt-{{ uid }} .rt-left {
  width: 100%;
  background: var(--rt-bg);
  color: var(--rt-text);
  padding: 24px;
  display: flex;
  align-items: center;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-left {
    width: 50%;
    padding: 48px;
  }
}

.rt-{{ uid }} .rt-content {
  width: 100%;
  max-width: 820px;
}

.rt-{{ uid }} .rt-head {
  font-size: 32px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-head-line {
  display: block;
}

.rt-{{ uid }} .rt-head-line + .rt-head-line {
  margin-top: 8px;
}

.rt-{{ uid }} .rt-desc {
  font-size: 16px;
  max-width: 600px;
  margin: 0 0 24px;
  color: #fff;
}

.rt-{{ uid }} .rt-btn {
  display: inline-block;
  padding: 16px 24px;
  background: var(--rt-btn-bg);
  color: var(--rt-btn-text);
  text-decoration: none;
  border-radius: 8px;
  font-weight: 700;
  transition: all .2s ease;
}

.rt-{{ uid }} .rt-btn:hover {
  background: var(--rt-btn-hover);
  transform: translateY(-2px);
  box-shadow: 0 10px 15px -3px rgba(0,0,0,.10);
}

.rt-{{ uid }} .rt-right {
  width: 100%;
  height: 220px;
  position: relative;
  background: var(--rt-bg);
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-right {
    width: 50%;
    height: auto;
  }
}

.rt-{{ uid }} .rt-right svg {
  display: none;
  width: 100%;
  height: 100%;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-right svg {
    display: block;
  }
}

.rt-{{ uid }} .rt-mobile-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

@media (min-width: 768px) {
  .rt-{{ uid }} .rt-mobile-img {
    display: none;
  }
}
</style>

<div class="rt-wrap rt-{{ uid }}">
  <div class="rt-banner">
    <div class="rt-left">
      <div class="rt-content">
        <h2 class="rt-head">
          <span class="rt-head-line">{{ title }}</span>
          <span class="rt-head-line">{{ subtitle }}</span>
        </h2>

        <p class="rt-desc">{{ description }}</p>

        <a href="{{ button_link }}" class="rt-btn">{{ button_label }}</a>
      </div>
    </div>

    <div class="rt-right">
      <svg viewBox="0 0 700 {{ banner_h }}" preserveAspectRatio="xMinYMid slice" aria-hidden="true">
        <defs>
          <clipPath id="imgClip-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
          <clipPath id="shadowOnPhotoSide-{{ uid }}">
            <polygon points="{{ diag_top_x }},0 700,0 700,{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>

          <filter id="sh_fold_soft-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="24" dy="1" stdDeviation="16" flood-color="#000" flood-opacity="0.14"/>
          </filter>

          <filter id="sh_band_only-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow in="SourceAlpha" dx="27" dy="17" stdDeviation="4.8" flood-color="#000" flood-opacity="0.22" result="ds1"/>
            <feDropShadow in="SourceAlpha" dx="52" dy="30" stdDeviation="26" flood-color="#000" flood-opacity="0.12" result="ds2"/>
            <feMerge>
              <feMergeNode in="ds1"/>
              <feMergeNode in="ds2"/>
            </feMerge>
          </filter>

          <linearGradient id="bandShine-{{ uid }}" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ffffff" stop-opacity="0.00"/>
            <stop offset="25%" stop-color="#ffffff" stop-opacity="0.22"/>
            <stop offset="50%" stop-color="#ffffff" stop-opacity="0.06"/>
            <stop offset="75%" stop-color="#ffffff" stop-opacity="0.18"/>
            <stop offset="100%" stop-color="#ffffff" stop-opacity="0.00"/>
          </linearGradient>

          <clipPath id="bandClip-{{ uid }}">
            <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}"></polygon>
          </clipPath>
        </defs>

        {% if img_url_700 != blank %}
          <image
            href="{{ img_url_700 }}"
            x="0"
            y="0"
            width="700"
            height="{{ banner_h }}"
            clip-path="url(#imgClip-{{ uid }})"
            preserveAspectRatio="xMidYMid slice"
          />
        {% else %}
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="#eee" clip-path="url(#imgClip-{{ uid }})" />
        {% endif %}

        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" filter="url(#sh_band_only-{{ uid }})"/>
        <polygon points="{{ diag_at_band_y }},{{ band_top_y }} {{ diag_at_band_y | plus: band_w }},{{ band_top_y }} {{ diag_bottom_x | plus: band_w }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#008CD2"/>

        <g clip-path="url(#bandClip-{{ uid }})" opacity="0.9">
          <rect x="0" y="0" width="700" height="{{ banner_h }}" fill="url(#bandShine-{{ uid }})"/>
        </g>

        <g clip-path="url(#shadowOnPhotoSide-{{ uid }})">
          <g filter="url(#sh_fold_soft-{{ uid }})">
            <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
          </g>
        </g>

        <polygon points="{{ diag_top_x | minus: fold_w }},0 {{ diag_top_x }},0 {{ diag_bottom_x }},{{ banner_h }} {{ diag_bottom_x | minus: fold_w }},{{ banner_h }}" fill="#003878"/>
        <polygon points="{{ diag_top_x }},0 {{ diag_top_x | plus: 2 }},0 {{ diag_bottom_x | plus: 2 }},{{ banner_h }} {{ diag_bottom_x }},{{ banner_h }}" fill="#000" opacity="0.06"/>
      </svg>

      {% if img_url_mobile != blank %}
        <img
          src="{{ img_url_mobile }}"
          class="rt-mobile-img"
          alt="{{ image_alt | escape }}"
          loading="lazy"
          decoding="async"
          fetchpriority="low"
          width="800"
          height="380"
        >
      {% else %}
        <div class="rt-mobile-img" style="background:#eee;"></div>
      {% endif %}
    </div>
  </div>
</div>
